-- =============================================================================
-- V60 — Website images live in frontend/img/ and are registered in the console (owner decision
-- 2026-11-09). Generated by the image move; hand edits are not expected.
--
--   * media_asset.external_url may now also be a website path under /img/ (files shipped with the
--     website, deployed with it to Render). The console shows them from the website address.
--   * The old admin's hotel and room photos (uploads/) become console gallery photos, published,
--     placed after any photo the hotel already has; the old hero becomes the cover only when the
--     hotel has none.
--   * Website positions (site_image_slot) default to the copies in /img/. A current image is
--     cleared only when it is exactly the external link that was copied, so an image an Admin
--     chose later is kept.
-- Idempotent: every insert skips rows that already exist.
-- =============================================================================

ALTER TABLE media_asset DROP CONSTRAINT media_asset_external_https;
ALTER TABLE media_asset ADD CONSTRAINT media_asset_external_https
    CHECK (external_url IS NULL OR external_url ~ '^https://[^[:space:]]+$' OR external_url ~ '^/img/[A-Za-z0-9._/-]+$');


INSERT INTO media_asset (id, partner_id, external_url, mime_type, category, status, visibility)
SELECT '56643730-cb32-5162-a029-e8bdce2a557f', p.partner_id, '/img/hotels/kas-passion-boutique-hotel/gallery/lobby/kas-passion-boutique-hotel-lobby-01.jpg', 'image/jpeg', CAST('LOBBY' AS media_category), 'PUBLISHED', 'PUBLIC'
  FROM property p WHERE p.slug = 'kas-passion-boutique-hotel'
ON CONFLICT DO NOTHING;
INSERT INTO media_asset_translation (media_asset_id, locale, alt_text)
SELECT a.id, v.locale, v.alt FROM media_asset a CROSS JOIN (VALUES ('vi', 'KAS Passion Boutique Hotel – Sảnh & lễ tân'), ('en', 'KAS Passion Boutique Hotel – Lobby')) v(locale, alt)
 WHERE a.external_url = '/img/hotels/kas-passion-boutique-hotel/gallery/lobby/kas-passion-boutique-hotel-lobby-01.jpg'
ON CONFLICT (media_asset_id, locale) DO NOTHING;

INSERT INTO media_link (media_asset_id, owner_type, owner_id, display_order, is_cover, status)
SELECT a.id, 'PROPERTY', p.id, 100, false, 'PUBLISHED' FROM media_asset a, property p
 WHERE a.external_url = '/img/hotels/kas-passion-boutique-hotel/gallery/lobby/kas-passion-boutique-hotel-lobby-01.jpg' AND p.slug = 'kas-passion-boutique-hotel'
ON CONFLICT (owner_type, owner_id, media_asset_id) DO NOTHING;

UPDATE media_link l SET is_cover = true FROM media_asset a, property p
 WHERE l.media_asset_id = a.id AND a.external_url = '/img/hotels/kas-passion-boutique-hotel/gallery/lobby/kas-passion-boutique-hotel-lobby-01.jpg' AND p.slug = 'kas-passion-boutique-hotel'
   AND l.owner_type = 'PROPERTY' AND l.owner_id = p.id
   AND NOT EXISTS (SELECT 1 FROM media_link c WHERE c.owner_type = 'PROPERTY' AND c.owner_id = p.id AND c.is_cover);

